import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
const read=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url))),ids=['saeon','leimma','pharma','runo','memoria'];
test('October 1 records five actual outputs without independent acceptance',()=>{const b=read('assets/citizen-work.json'),ds=b.deliveries.filter(d=>d.executionId==='daily-20261001-root');assert.deepEqual(ds.map(d=>d.citizenId).sort(),[...ids].sort());for(const d of ds){assert.equal(d.review,null);assert.equal(b.tasks.find(t=>t.id===d.taskId).state,'awaiting_review');}});
test('October 1 publications, attachments and multilingual work links exist',()=>{for(const id of ids){const n=read(`research/2026-10-01/${id}.json`);for(const l of ['zh','en','ko']){for(const k of ['title','lead','limitation','next'])assert.ok(n[k][l]);const a=read(`assets/agents${l==='zh'?'':'.'+l}.json`);assert.ok(a.find(a=>a.id===id).works.some(w=>w.publicationId===`2026-10-01-${id}`));}for(const a of n.attachments)assert.ok(fs.existsSync(new URL('../'+a.path,import.meta.url)));}});
test('new source observation does not overwrite the historical access failure or probabilities',()=>{const old=read('research/2026-09-29/source-checks.json'),fresh=read('research/2026-10-01/source-checks.json');assert.equal(old.sources.filter(s=>s.httpStatus===403).length,2);assert.equal(fresh.sources.find(s=>s.url.includes('ftc.gov')).status,'selected_sections_read');assert.equal(fresh.sources.find(s=>s.url.includes('37111')).eventDate,'2026-09-30');const c=read('research/2026-09-25/cynosure-forecasts.json').cards;assert.deepEqual(c.map(x=>x.probability),[.65,.55]);assert.ok(c.every(x=>x.outcome===null));});
test('four missing deliveries remain explicit rather than acquiring publication IDs',()=>{const f=read('assets/research-frontiers.json');for(const id of ['sigma','nullroute','vox','cynosure'])for(const l of ['zh','en','ko']){const r=f.citizens[id][l].find(x=>x.observationId===`2026-10-01-gap-${id}`);assert.ok(r);assert.equal(r.publicationId,undefined);assert.equal(r.evidenceStatus,'hypothesis');}});
